target.css:
:root {
  --ink: #252239;
  --muted: #706d83;
  --paper: #fffdf9;
  --line: #ded9eb;
  --violet: #7057d9;
  --violet-soft: #eeeaff;
  --mint: #c8f0dc;
  --mint-ink: #21674d;
  --yellow: #ffd85a;
  --yellow-ink: #715800;
}

.order-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 14px;
  border-bottom: 1px solid var(--line);
}

.keycap-mark {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  margin: 0;
  background: var(--violet);
  border: 3px solid var(--ink);
  border-radius: 10px;
  color: var(--paper);
  font-size: 20px;
  font-weight: 800;
}

.title-block {
  flex: 1;
}

.eyebrow,
.section-label {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

h1 {
  margin: 2px 0 0;
  font-size: 20px;
  line-height: 1.1;
}

.status-badge {
  padding: 5px 8px;
  background: var(--mint);
  border-radius: 999px;
  color: var(--mint-ink);
  font-size: 11px;
  font-weight: 800;
}

.build-grid {
  display: grid;
  grid-template-columns: 1fr 1.08fr;
  gap: 10px;
  padding: 14px 0;
}

.spec-panel,
.feel-panel {
  padding: 11px;
  border-radius: 12px;
}

.spec-panel {
  background: var(--violet-soft);
}

.feel-panel {
  border: 1px solid var(--line);
}

.spec-list {
  display: grid;
  gap: 7px;
  margin: 9px 0 0;
  padding: 0;
  list-style: none;
}

.spec-list li,
.sound-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  font-size: 12px;
}

.spec-list span,
.sound-row span {
  color: var(--muted);
}

.spec-list strong,
.sound-row b {
  font-size: 12px;
}

.sound-row {
  justify-content: flex-start;
  margin-top: 8px;
}

.sound-row b {
  margin-left: auto;
  color: var(--violet);
}

.sound-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.dot-one { background: var(--violet); }
.dot-two { background: var(--mint-ink); }
.dot-three { background: var(--yellow); }

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 12px;
}

button {
  padding: 8px 12px;
  background: var(--yellow);
  border: 1px solid var(--ink);
  border-radius: 8px;
  color: var(--yellow-ink);
  font-size: 12px;
  font-weight: 800;
}

